#include "../../research/ExciterShapedFir.h"
#include <cstdio>
#include <fstream>
#include <chrono>
using namespace skl;
static double db(double x){return 20*std::log10(std::max(1e-15,x));}
struct Bin{double a=0,b=0;void add(float x,double phase){a+=x*std::cos(phase);b+=x*std::sin(phase);}double level(int n){return db(2*std::hypot(a,b)/n);}};
int main(int argc,char**argv){int aliasCases=0,desiredCases=0,bad=0;double maxFund=0,maxThird=0,minAlias=1000;for(int sr:{44100,48000,96000,192000})for(int f:{2200,4200,6200,7800,10200,12500})for(float drive:{6.f,18.f}){if(f>=sr/2)continue;ExciterCandidate a;a.prepare(sr);a.set(1000,drive,.6f,12000);research::ExciterShapedFir<257> b;b.prepare(sr);b.set(1000,drive,.6f,12000);Bin x,y,h,i;const int third=std::abs((3*f+sr/2)%sr-sr/2),len=sr/5;for(int n=0;n<2*len;++n){float v=.4f*std::sin(2*kPi*f*n/sr),u=a.process(0,v),w=b.process(0,v);if(n>=len){x.add(u,2*kPi*f*n/sr);y.add(w,2*kPi*f*n/sr);h.add(u,2*kPi*third*n/sr);i.add(w,2*kPi*third*n/sr);}}const double fund=y.level(len)-x.level(len),harm=i.level(len)-h.level(len);maxFund=std::max(maxFund,std::abs(fund));if(h.level(len)>-100){if(3*f<sr/2){++desiredCases;maxThird=std::max(maxThird,std::abs(harm));bad+=std::abs(harm)>1;}else{++aliasCases;minAlias=std::min(minAlias,-harm);}}std::printf("%d %d %.0f: fundamental delta %.2f dB, %s third %.2f -> %.2f delta %.2f dB\n",sr,f,drive,fund,3*f<sr/2?"desired":"folded",h.level(len),i.level(len),harm);}std::printf("Holdout %d desired, %d exceed 1 dB; max desired %.3f, max fundamental %.3f; %d alias cases, min reduction %.3f dB\n",desiredCases,bad,maxThird,maxFund,aliasCases,minAlias);
 for(int j=1;j<argc;++j){std::ifstream in(argv[j],std::ios::binary|std::ios::ate);if(!in)return 2;std::vector<float>x(size_t(in.tellg())/4),aout(x.size()),bout(x.size());in.seekg(0);in.read(reinterpret_cast<char*>(x.data()),x.size()*4);ExciterCandidate a;a.prepare(48000);a.set(3500,9,.35f,12000);research::ExciterShapedFir<257> b;b.prepare(48000);b.set(3500,9,.35f,12000);using Clock=std::chrono::steady_clock;auto start=Clock::now();for(size_t n=0;n<x.size();++n)aout[n]=a.process(0,x[n]);const auto mid=Clock::now();for(size_t n=0;n<x.size();++n)bout[n]=b.process(0,x[n]);const auto end=Clock::now();double error=0,energy=0,peak=0;const auto d=b.latency;for(size_t n=1000;n+d<x.size();++n){double u=aout[n],v=bout[n+d];error+=(u-v)*(u-v);energy+=u*u;peak=std::max(peak,std::abs(v));}std::printf("Fixture %d relative null %.2f dB, peak %.2f dBFS, current %.2f ms, shaped %.2f ms\n",j,10*std::log10(error/energy),db(peak),std::chrono::duration<double,std::milli>(mid-start).count(),std::chrono::duration<double,std::milli>(end-mid).count());}
}
